public class Reporter_noMoreInteractionsWantedInOrder_TriageGen2Test {

    @Test
    public void testNoMoreInteractionsWantedInOrderThrowsVerificationInOrderFailure() {
        // Arrange
        Reporter reporter = new Reporter();
        Invocation undesired = mock(Invocation.class);
        Object mockObject = new Object();
        Location undesiredLocation = new LocationImpl();

        when(undesired.getMock()).thenReturn(mockObject);
        when(undesired.getLocation()).thenReturn(undesiredLocation);

        // Act & Assert
        try {
            reporter.noMoreInteractionsWantedInOrder(undesired);
            org.junit.Assert.fail("Expected VerificationInOrderFailure to be thrown");
        } catch (VerificationInOrderFailure failure) {
            String message = failure.getMessage();

            // Verify the content of the error message matches the logic in the method
            // "No interactions wanted here:" + LocationImpl + "But found this interaction on mock '" + mock + "':" + location
            assertTrue("Message should contain 'No interactions wanted here:'", 
                    message.contains("No interactions wanted here:"));
            assertTrue("Message should contain the mock object string representation", 
                    message.contains("But found this interaction on mock '" + mockObject + "':"));
            assertTrue("Message should contain the location description", 
                    message.contains(undesiredLocation.toString()));
        }
    }
}
